package org.sleepwell.app;
import android.app.*;import android.content.Intent;import android.os.*;import android.view.View;import android.widget.LinearLayout;
/** Explicit reviewed replacement. No picker result or recreation can silently start a restore. */
public final class LibraryAudioImportActivity extends Activity implements LibraryAudioImportJob.Observer {
 private static final int OPEN=468;private LibraryAudioImportJob job;private Dialog confirm;
 @Override public void onCreate(Bundle saved){super.onCreate(saved);RecordUi.review(this);Object retained=getLastNonConfigurationInstance();job=retained instanceof LibraryAudioImportJob?(LibraryAudioImportJob)retained:new LibraryAudioImportJob(getApplicationContext(),Records.factory,saved!=null);job.observe(this);if(saved==null&&!(retained instanceof LibraryAudioImportJob)&&getIntent().hasExtra("document")){String document=getIntent().getStringExtra("document"),sha=getIntent().getStringExtra("expectedSha");if(document!=null&&sha!=null&&sha.matches("[a-f0-9]{64}")&&job.choose())job.read(android.net.Uri.parse(document),sha);}if(Build.VERSION.SDK_INT>=33)getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,this::back);}
 @Override public Object onRetainNonConfigurationInstance(){return job;}
 public void changed(LibraryAudioImportJob.State state){if(isDestroyed())return;LinearLayout body=Design.page(this,false,null,n->{});RecordUi.label(this,body);RecordUi.header(body,"Restore audio backup",this::back);Design.space(body,16);Design.text(body,"Import a version 2 SleepWell audio-library ZIP. Older export-only ZIPs cannot restore records.",14,400,Design.MUTED);Design.space(body,16);if(state.review!=null){LibraryAudioImport.Review review=state.review;Design.item(body,"bell","Saved alarms",""+review.backup.optJSONArray("alarms").length(),null);Design.item(body,"moon","Sleep records",""+review.backup.optJSONArray("sessions").length(),null);Design.item(body,"wave","Complete recordings",""+review.audio.size(),null);Design.item(body,"file","Sound events",""+review.backup.optJSONArray("sound_events").length(),null);Design.item(body,"upload","Audio size",android.text.format.Formatter.formatShortFileSize(this,review.bytes),null);Design.space(body,14);Design.text(body,"Replaces all local alarms, sleep records and saved audio with this backup. Imported alarms remain off. App settings and account credentials stay unchanged. Full clips may include audio outside edited sleep times.",14,500,Design.BROWN);}Design.space(body,12);if(!state.message.isEmpty())Design.text(body,state.message,14,500,state.phase==LibraryAudioImportJob.Phase.ERROR?0xffa93919:Design.MUTED);LinearLayout footer=RecordUi.footer(body);if(state.phase==LibraryAudioImportJob.Phase.REVIEW){Design.button(footer,"Review replacement…",true,this::confirm);Design.button(footer,"Cancel import",false,this::finish);}else if(state.phase==LibraryAudioImportJob.Phase.READING||state.phase==LibraryAudioImportJob.Phase.RESTORING){Design.text(footer,state.phase==LibraryAudioImportJob.Phase.READING?"Validating ZIP…":"Finishing restore…",14,500,Design.BROWN);if(state.phase==LibraryAudioImportJob.Phase.READING)Design.button(footer,"Cancel import",false,this::finish);}else{View choose=Design.button(footer,"Choose audio ZIP",true,this::choose);RecordUi.enabled(choose,state.phase!=LibraryAudioImportJob.Phase.CHOOSING);}}
 private void choose(){if(!job.choose())return;try{startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("application/zip").putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"application/zip","application/x-zip-compressed","application/octet-stream"}),OPEN);}catch(android.content.ActivityNotFoundException absent){job.choiceCancelled();SleepPicker.message(this,"No document picker","Enable Android Files to choose an audio ZIP.");}}
 private void confirm(){if(confirm!=null&&confirm.isShowing()||job.state().phase!=LibraryAudioImportJob.Phase.REVIEW)return;confirm=new AlertDialog.Builder(this).setTitle("Replace local data and audio?").setMessage("Only the reviewed backup will remain in local history. Imported alarms stay off. This replacement cannot be cancelled once started.").setNegativeButton("Keep local data",(d,w)->{}).setPositiveButton("Replace with backup",(d,w)->job.confirm()).create();confirm.show();ReportDialogs.style((AlertDialog)confirm);}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=OPEN)return;if(result!=RESULT_OK||data==null||data.getData()==null)job.choiceCancelled();else job.read(data.getData());}
 private void back(){if(job.restoring())Ui.toast(this,"Finishing the restore. Please wait.");else finish();}
 @Override public void onBackPressed(){back();}
 @Override protected void onDestroy(){if(confirm!=null)confirm.dismiss();job.detach(this);if(!isChangingConfigurations())job.close();super.onDestroy();}
 @Override protected void onPostResume(){super.onPostResume();RecordUi.lightBars(this);}
 @Override public void onWindowFocusChanged(boolean focus){super.onWindowFocusChanged(focus);if(focus)RecordUi.lightBars(this);}
}
